  Object.assign(os.find((o) => o.num === 508), { pago: true, entregueDia: -30, receb: { forma: 'PIX', parcelas: 1, desconto: 0, total: 396 }, satisf: { nota: 5, coment: 'Rápido e explicaram tudo.' }, comissionada: true });
