  Object.assign(os.find((o) => o.num === 508), { orcado: true, recusados: [{ nome: 'Troca de amortecedores (par)', valor: 380 }], kmMes: 1400 }); Object.assign(os.find((o) => o.num === 503), { orcado: true, kmMes: 800 }); os.find((o) => o.num === 513).prontoDia = -4; os.find((o) => o.num === 516).prontoDia = 0;
  Object.assign(os.find((o) => o.num === 517), { orcHoras: 3, insp: { 0: 'v', 1: 'v', 2: 'v', 3: 'r', 4: 'v', 5: 'v', 6: 'a', 7: 'v', 8: 'v', 9: 'a', 10: 'v', 11: 'v', 12: 'a', 13: 'v', 14: 'a', 15: 'v', 16: 'a', 17: 'v', 18: 'v', 19: 'v' } });
  Object.assign(os.find((o) => o.num === 512), { checklist: { comb: '1/2', km: 121056, avarias: 'Risco no para-choque traseiro', objetos: 'Cadeirinha no banco de trás' } });
  Object.assign(os.find((o) => o.num === 514), { encomenda: { forn: 'Suspensão Forte', chega: 1, peca: 'Amortecedores dianteiros (par)' } });
  const estoque = [['W712/95', 'Filtro de óleo', 'VW/Fiat/GM 1.0-1.6', 3, 10, 21, 48, 'Distribuidora Autopeças BH'], ['PD/1043', 'Pastilhas dianteiras', 'Argo/Cronos', 2, 4, 88, 198, 'Freios Center'], ['BD1745', 'Discos de freio (par)', 'Argo/Cronos/Mobi', 1, 2, 210, 420, 'Freios Center'], ['5W40-VW', 'Óleo 5W40 (4 L)', 'VW TSI', 6, 6, 128, 236, 'Lubrificantes Minas'], ['CT1201K2', 'Kit correia dentada', 'Compass/Renegade 2.0', 0, 1, 470, 845, 'Distribuidora Autopeças BH'], ['GP32988', 'Amortecedores dianteiros (par)', 'S10/Trailblazer', 0, 1, 690, 1260, 'Suspensão Forte'], ['PD/1180', 'Pastilhas dianteiras', 'HR-V/City/Fit', 5, 4, 104, 236, 'Freios Center'], ['VELA-NGK-6', 'Jogo de velas', '1.0/1.6 flex', 12, 6, 64, 148, 'Distribuidora Autopeças BH']]
    .map(([cod, nome, apl, qtd, min, custo, preco, forn]) => ({ cod, nome, apl, qtd, min, custo, preco, forn }));
  const agenda = [{ id: novoId(), nome: 'Rodrigo Alves', tel: '31992221100', placa: 'TYU6K45', modelo: 'Nissan Kicks 2021', servico: 'Revisão completa', dia: 1, hora: 9, status: 'pedido', origem: 'link do Instagram' }, { id: novoId(), nome: 'Sandra Melo', tel: '31998887766', placa: 'GHJ2L33', modelo: 'Fiat Toro 2019', servico: 'Troca de óleo e filtro', dia: 1, hora: 14, status: 'pedido', origem: 'Google' }, { id: novoId(), nome: 'Paulo Henrique', tel: '31993334455', placa: 'BNM1M22', modelo: 'Corolla 2018', servico: 'Alinhamento e balanceamento', dia: 2, hora: 10, status: 'confirmado', origem: 'WhatsApp' }];
  const historico = [['Lucas Andrade', '31991112233', 'ZXC7N88', 'Gol 2015', -200], ['Fernanda Lopes', '31994443322', 'VBN9P11', 'Onix 2019', -175], ['Ricardo Silva', '31996661199', 'ASD3Q44', 'HB20 2018', -40], ['Mônica Prado', '31997775533', 'QWE5R66', 'Kwid 2020', -380]].map(([nome, tel, placa, modelo, ultima], i) => ({ nome, tel, placa, modelo, ultima, km: [82000, 54000, 61000, 38000][i], kmMes: [1500, 900, 2000, 700][i] }));
  const SAIDA = { 'VELA-NGK-6': 140, 'PD/1180': 95, '5W40-VW': 12 }; estoque.forEach((p) => { p.ultSaida = SAIDA[p.cod] ?? 8; });
  const recalls = [{ id: 'rc1', montadora: 'Jeep', modelo: 'Compass', anos: [2020, 2021], desc: 'airbag do motorista pode não abrir numa colisão' }, { id: 'rc2', montadora: 'Fiat', modelo: 'Argo', anos: [2022], desc: 'bomba de combustível pode falhar com o motor quente' }];
