  checklist: (d) => { const o = ordem(d.o); form(`Entrada · ${e(o.placa)}`, `<div class="dois-o"><label class="cmp">Combustível<select name="c">${['Reserva', '1/4', '1/2', '3/4', 'Cheio'].map((x) => `<option>${x}</option>`).join('')}</select></label><label class="cmp">Quilometragem<input name="k" type="number" min="0" required value="${o.km || ''}"></label></div><label class="cmp">Avarias que o carro já tinha<input name="a" placeholder="ex.: risco na porta direita"></label><label class="cmp">Objetos deixados no carro<input name="b" placeholder="ex.: estepe, documentos"></label>`, 'Registrar', (f) => { const k = Math.round(Number(f.get('k'))); if (!(k > 0)) { toast('Informe a quilometragem.'); return false; } o.checklist = { comb: f.get('c'), km: k, avarias: String(f.get('a') || '').trim(), objetos: String(f.get('b') || '').trim() }; o.km = k; toast('Entrada registrada. Vai junto com o orçamento para o cliente.'); }); },
